// Passes the get_usage answer through as a readable summary.
// Run this before any scheduled sending workflow so you can see
// how much of today's per-account limits are already used.
const first = $input.all()[0].json;
if (!first.ok) {
  return [{ json: { brief: 'HeyReagent call failed: ' + (first.message || first.error || 'unknown error') } }];
}
return [{ json: { brief: 'HeyReagent usage today:\n' + JSON.stringify(first.result || {}, null, 2) } }];
